/**
 * Express entry — acme-health.
 *
 * Generated by workshop-demo-generator. The Twilio packages (`src/relay/`,
 * `src/channels/`, …) add their HTTP routes here and, when they need it, attach to
 * the `http.Server` for WebSocket support. Every router the app's own handlers
 * serve is listed in `src/handlers/` and mounted below. See CLAUDE.md.
 */

import 'dotenv/config'
import { createServer } from 'http'
import express, { type Request, type Response } from 'express'

// Observability is always on: every app records its Twilio events (§6).
import { initStore, router as eventsRouter } from './observability.js'
import { ROUTERS } from './handlers/index.js'

import { router as channelsRouter } from './channels/index.js'

import { router as relayRouter } from './relay/index.js'


export function createApp() {
  const app = express()
  // Keep the raw JSON body: Twilio's JSON webhooks are signed over it (bodySHA256).
  app.use(
    express.json({
      verify: (req, _res, buf) => {
        ;(req as Request & { rawBody?: string }).rawBody = buf.toString('utf8')
      },
    }),
  )
  app.use(express.urlencoded({ extended: false }))

  app.get('/health', (_req: Request, res: Response) => {
    res.json({ status: 'ok' })
  })

  initStore() // create the events table before serving (§6)
  app.use(eventsRouter) // GET /events (§6)

  app.use(channelsRouter)

  app.use(relayRouter)


  for (const router of ROUTERS) app.use(router) // the app's own handlers (src/handlers/)

  return app
}

const app = createApp()
const server = createServer(app)

// Attach the ConversationRelay WebSocket (/relay/ws) to the same http.Server as Express.
import { attachRelayWebSocket } from './relay/index.js'

attachRelayWebSocket(server)


const port = Number(process.env.PORT ?? 8080)
server.listen(port, '0.0.0.0', () => {
  // eslint-disable-next-line no-console
  console.log(`acme-health listening on http://0.0.0.0:${port}`)
})
